/* ============================= */
/* Dashboard background */
/* ============================= */
html, body, .grafana-app, .main-view {
  background-color: #0b1220 !important;
}

/* ============================= */
/* Panels background */
/* ============================= */
.panel-container,
.panel-content,
.dashboard-container {
  background-color: #111827 !important;
}

/* ============================= */
/* Text colors */
/* ============================= */
body, div, span, p {
  color: #e5e7eb !important;
}

/* Secondary text */
.text-muted,
.panel-title,
.css-1d7b7hu {
  color: #9ca3af !important;
}

/* ============================= */
/* Links & highlights */
/* ============================= */
a {
  color: #60a5fa !important;
}
